CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, phone TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, category TEXT NOT NULL, title_en TEXT NOT NULL, title_pt TEXT NOT NULL, description_en TEXT DEFAULT '', description_pt TEXT DEFAULT '', original_price NUMERIC(12,2) NOT NULL, colors TEXT[] DEFAULT '{}', images TEXT[] DEFAULT '{}', sizes TEXT[] DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id), email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending_payment', items JSONB NOT NULL, address JSONB NOT NULL, subtotal NUMERIC(12,2) NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS wishlist (user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id) ON DELETE CASCADE, PRIMARY KEY(user_id, product_id));
CREATE TABLE IF NOT EXISTS addresses (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, data JSONB NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS page_visits (id BIGSERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id), session_id TEXT NOT NULL, path TEXT NOT NULL, product_id INTEGER REFERENCES products(id), duration_seconds INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
